-- Recording queue rows for the Google Tag Manager guide narration
-- (bcpsmarcomm.com/tag-manager-guide), re-voiced in Sean's voice 2026-11-06.
-- canon process-recording-queue. Safe to run twice.
insert into public.recording_queue (slug, brand_slug, title, kind, status, position, batch, purpose, surface_url, script, direction, est_seconds, placeholder_url, target, source, notes, created_by)
select 'gtm-guide-'||id, 'bcps', 'Tag Manager Guide: '||title, 'narration', 'needs_approval', pos, 'gtm-guide',
 'Narration for the "'||title||'" slide ('||pth||')', 'https://bcpsmarcomm.com/tag-manager-guide?s='||id, script,
 'Warm, plain, unhurried. You are walking a colleague through it, not presenting.', secs,
 'https://bcpsmarcomm.com/audio/gtm-guide/'||id||'.mp3',
 jsonb_build_object('system','repo_public_audio','repo','lesaruss/bcpsmarcomm','path','public/audio/gtm-guide/'||id||'.mp3',
   'wire_in','Replace public/audio/gtm-guide/'||id||'.mp3 in lesaruss/bcpsmarcomm with the take (mono, 44.1 kHz, 128k mp3), commit and deploy. The page plays that file on slide '||id||'.',
   'live_url','https://bcpsmarcomm.com/audio/gtm-guide/'||id||'.mp3'),
 'Higgsfield seed_audio, voice element 7985695a (Sean A. Russell), speech_rate -5, job '||job||', 2026-11-06; prompt = the script. Live as the AI placeholder at Sean''s request.'||case when id='end' then ' Take added a stray "Today" after the script; trimmed at 16.3 s.' else '' end,
 'AI take in Sean''s voice is live on the guide (Sean, 2026-11-06: "use my voice for the narration instead"). Transcript checked against the script. A recorded take replaces it at the same path.', 'logan'
from (values
('welcome',1,'Google Tag Manager at BCPS','shared opening','Welcome. This short guide explains how Broward County Public Schools manages Google Tag Manager on browardschools dot com, and what happens when a department wants an outside agency to track a campaign. It takes about four minutes. Press Next whenever you are ready.',18,'f374445e'),
('what',2,'What Tag Manager does','shared opening','Google Tag Manager is a small piece of code that loads on every page of browardschools dot com. Inside it, people add tags: small instructions that send information to tools like Google Analytics, Google Ads, or Meta. The website itself never changes. That makes it powerful, and it is exactly why it needs one clear owner.',24,'20dd4830'),
('why',3,'Why the District manages it','shared opening','Anything added to Tag Manager can run on every District page, and it decides what information leaves our site. Access also has a way of lingering long after a campaign ends. So the District Web Team keeps one record of who has access, what they track, and when that access closes. Departments still run their campaigns. We just make sure it is done the right way.',24,'c7d3f041'),
('rule',4,'One container. One owner.','shared opening','There are two Tag Manager containers on our site. One belongs to Finalsite, our website vendor. It is shared with their other clients, so it is not ours to give out. The other is the District''s own container. Every agency works there, in its own workspace, and no department creates a container of its own.',22,'990856f2'),
('choose',5,'Which one are you?','shared opening','Now pick the path that fits you. If your department is working with an agency on a campaign, choose the first card. If you are on the District Web Team and manage the container, choose the second.',13,'ccf5fc1b'),
('request',6,'Send us your request','department path','Step one. Send the District Web Team a short request, approved by your director. It covers who the agency is, who needs access, the campaign dates, and what will be tracked. We keep it on file, so we can always answer who is tracking what, and until when.',18,'0e4c0841'),
('rules',7,'What your agency gets','department path','Step two. Your agency gets edit access in its own workspace. Their tags run only on your department''s pages, and every tag name starts with your department, like Magnet. They never change District tags, and they never collect personal information. No names, no emails, nothing typed into a form.',27,'1cc8f2b2'),
('golive',8,'Build, review, go live','department path','Step three. The agency builds and tests its tags in preview mode, then lets us know it is ready. The District Web Team reviews the changes and publishes them, the same business day during a campaign window. Nothing goes live on the District site without that check.',20,'a18f68d0'),
('end',9,'When the campaign ends','department path','Step four. On the campaign end date, the agency''s tags are paused and their access is removed. If you need more time, just ask before the end date and we will extend it. That is everything a department needs to know.',16,'45b1cfc4'),
('record',10,'Record it in the Tag Register','District Web Team path','Step one. When a department sends its request, open the Tag Register, find the agency, and click Open. Fill in the three steps: the agency and its people, the dates and approval, and their answers. Then save. If it is not in the register, it does not get access.',20,'1ecd3d58'),
('invite',11,'Invite them in Tag Manager','District Web Team path','Step two. Open the District container in Tag Manager. Click Admin, then Container User Management, then the plus button, and Add users. Type each person''s email from the register, set the permission to Edit, not Publish, and click Invite. Google emails each of them an invitation.',23,'64c0ce22'),
('open',12,'Open their access','District Web Team path','Step three. Back in the Tag Register, click Open access on their record. It turns green and records today''s date, so the register always shows when access started.',14,'372d16a5'),
('publish',13,'Review, then publish','District Web Team path','Step four. When the agency says it is ready, ask Logan for the workspace review. It checks that every tag is named for the department, fires only on its pages, and leaves District tags alone. If it passes, open their workspace in Tag Manager, click Submit, then Publish. If it fails, send them the list of fixes.',27,'cd2313c7'),
('close',14,'Close it out','District Web Team path','Step five. On the end date, go back to Container User Management, select their names, and remove them. Pause their tags. Then click Close access in the Tag Register. Access that ends on time is the whole point.',18,'5743b194'),
('quarterly',15,'Glance at the colors','District Web Team path','Finally, once a quarter, open the Tag Register and glance at the colors. Orange means a close date is missing or coming up. Red means access is past its end date and still open, so act on it. Anything that needs you sorts to the top.',23,'563a50f3'),
('done',16,'That''s the whole process.','shared opening','That is the whole process. One container, one record, and access that always has an end date. Thank you for helping keep browardschools dot com safe and well run.',12,'10a460e6')
) as v(id, pos, title, pth, script, secs, job)
where not exists (select 1 from public.recording_queue r where r.slug = 'gtm-guide-'||v.id)
returning slug;
